	private Boolean processPins(String cardNumber, CS status, String user, String department) {
		logger.info("Radi aktivaciju pina cardNumber {}", cardNumber);
		List<Perso> pinPerso = persoRepo.findByCardNumber(cardNumber);
		LocalDateTime currentDateTime = LocalDateTime.now();

		if (pinPerso.isEmpty()) {
			throw new CardActivationException(400, "Gre­ka: Ne nalazimo karticu: " + cardNumber +
					", pa je nemoguŽØe promeniti status na activated.", "Process error", ACTIVATE_CARD_URL + cardNumber);
		}

		// Filtriramo samo redove gde je type = 'p'
		List<Perso> validPins = pinPerso.stream()
				.filter(perso -> "p".equals(perso.getType()))
				.collect(Collectors.toList());

		if (validPins.isEmpty()) {
			throw new CardActivationException(400, "Gre­ka: Nema validnog PIN-a za karticu: " + cardNumber +
					", pa je nemoguŽØe promeniti status na activated.", "Process error", ACTIVATE_CARD_URL + cardNumber);
		}

		for (Perso p : validPins) {
			logger.info("Processing Card: {}", p);
			p.setStatus(status.getId());
			p.setUpdatedAt(currentDateTime);
			p.setUpdatedBy(user);
			persoRepo.save(p);

			CardRegistrationHistory ch = createCardHistory(p.getId(), status.getId(), status.getText(), user, department);
			cardHistoryRepo.save(ch);
		}

		return true;
	}


	private CardRegistrationHistory createCardHistory(Integer persoId, String statusId, String status, String updatedBy,
