import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.*;
import org.springframework.stereotype.Service;
import org.springframework.web.client.RestClientException;
import org.springframework.web.client.RestTemplate;

import rs.unicredit.cardlifecycle.exception.CardActivationException;

@Service
public class ExternalServiceImpl implements ExternalService {

	private static final Logger logger = LoggerFactory.getLogger(ExternalServiceImpl.class);

	private final RestTemplate restTemplate;

	@Value("${customs.card-api.activate-card}")
	private String ACTIVATE_CARD_URL;

	@Value("${customs.card-api.api-key}")
	private String API_KEY;

	public ExternalServiceImpl(RestTemplate restTemplate) {
		this.restTemplate = restTemplate;
	}

	@Override
	public boolean activateCard(String cardNumber) {
	    String url = ACTIVATE_CARD_URL + cardNumber;
	    //logger.info("Sending request to activate card: {}", cardNumber);
		System.out.println("Aktivacija!"+cardNumber);
		System.out.println("url"+url);
		System.out.println("API_KEY"+API_KEY);
	    HttpHeaders headers = new HttpHeaders();
	    headers.set("x-api-key", API_KEY);
	    headers.setContentType(MediaType.APPLICATION_JSON);

	    HttpEntity<String> requestEntity = new HttpEntity<>("{}", headers);

	    try {
	        ResponseEntity<Map> response = restTemplate.exchange(url, HttpMethod.POST, requestEntity, Map.class);
			System.out.println("response!"+response);
	        var body = response.getBody();
	        if (body == null) {
	            logger.warn("Received empty response body for card activation request: {}", cardNumber);
	            throw new CardActivationException(500, "Empty response body", "Activation failed", url);
	        }

	        Object returnCode = body.get("returnCode");
	        boolean isActivated = "Y".equalsIgnoreCase(returnCode != null ? returnCode.toString() : "");

	        if (!isActivated) {
	            throw new CardActivationException(400, "Activation failed", "Invalid return code", url);
	        }

	        logger.info("Card activation result for {}: SUCCESS", cardNumber);
	        return true;

	    } catch (RestClientException e) {
	        logger.error("Error while calling Card Activation API for card {}: {}", cardNumber, e.getMessage());
	        throw new CardActivationException(400, "API error", e.getMessage(), url);
	    }
	}


}

